// The hosted Demiurges wiki. Articles are generated by tools/build_wiki.py into
// data/<lang>/index.json and data/<lang>/pages/<page>.json; this page only
// reads them. Addresses are /wiki/?lang=<lang>&page=<page>, so links, Back,
// Forward and reload all work without a server.
const $ = selector => document.querySelector(selector);
const LANGUAGES = ['en', 'ru'];
const STORAGE = 'demiurges.wiki.language';
const indexes = new Map();
const pages = new Map();
let strings = {};
let labels = {};
let index = null;

function stored() {
  try { return localStorage.getItem(STORAGE); } catch { return null; }
}
function remember(lang) {
  try { localStorage.setItem(STORAGE, lang); } catch { /* private window */ }
}

function route() {
  const params = new URLSearchParams(location.search);
  let lang = params.get('lang');
  if (!LANGUAGES.includes(lang)) lang = stored();
  if (!LANGUAGES.includes(lang)) lang = (navigator.language || '').toLowerCase().startsWith('ru') ? 'ru' : 'en';
  const page = params.get('page') || 'home';
  return {lang, page: /^[a-z0-9]+(-[a-z0-9]+)*$/.test(page) ? page : 'home'};
}

function href(page, lang = route().lang) {
  const params = new URLSearchParams({lang});
  if (page !== 'home') params.set('page', page);
  return '/wiki/?' + params;
}

async function json(url) {
  const response = await fetch(url, {cache: 'no-cache'});
  if (!response.ok) throw new Error(url + ': ' + response.status);
  return response.json();
}

function catalogue(lang) {
  if (!indexes.has(lang)) indexes.set(lang, json(`/wiki/data/${lang}/index.json`));
  return indexes.get(lang);
}
function article(lang, key) {
  const id = lang + '/' + key;
  if (!pages.has(id)) pages.set(id, json(`/wiki/data/${lang}/pages/${key}.json`));
  return pages.get(id);
}

function text(key, values = {}) {
  return (strings[key] || labels.en[key] || key).replace(/\{(\w+)\}/g, (_, name) => values[name] ?? '');
}

function translate(lang) {
  strings = labels[lang];
  document.documentElement.lang = lang;
  document.title = text('title');
  for (const node of document.querySelectorAll('[data-text]')) node.textContent = text(node.dataset.text);
  $('#search').placeholder = text('search');
  $('#language').value = lang;
  $('#brand').href = href('home', lang);
}

// Words the reader typed, in any order, each matching the start of a word or
// any part of a title.
function matches(entry, words) {
  const title = entry.title.toLowerCase();
  return words.every(word => title.includes(word) || entry.search.includes(word));
}

function results() {
  const {lang, page} = route();
  const query = $('#search').value.trim().toLowerCase();
  const words = query.split(/\s+/).filter(Boolean);
  const list = $('#results');
  list.replaceChildren();
  let found = 0;
  for (const category of index.categories) {
    const rows = index.entries.filter(entry => entry.category === category.id && matches(entry, words));
    if (!rows.length) continue;
    const group = document.createElement('section');
    const heading = document.createElement('h2');
    heading.textContent = category.title;
    group.append(heading);
    for (const entry of rows) {
      const link = document.createElement('a');
      link.href = href(entry.key, lang);
      link.textContent = entry.title;
      if (entry.summary && words.length) {
        const detail = document.createElement('small');
        detail.textContent = entry.summary;
        link.append(detail);
      }
      if (entry.key === page) link.setAttribute('aria-current', 'page');
      group.append(link);
      found++;
    }
    list.append(group);
  }
  $('#status').textContent = words.length ? (found ? text('found', {n: found}) : text('nothing')) : '';
}

function contents(node) {
  const toc = $('#toc');
  toc.replaceChildren();
  const headings = [...node.querySelectorAll('h2')];
  if (headings.length < 3) return;
  const title = document.createElement('h2');
  title.textContent = text('contents');
  toc.append(title);
  headings.forEach((heading, n) => {
    heading.id = 'section-' + (n + 1);
    const link = document.createElement('a');
    link.href = '#' + heading.id;
    link.textContent = heading.textContent;
    toc.append(link);
  });
}

function render(page, lang) {
  const node = $('#article');
  // The HTML is the generator's escaped subset; links are rewritten here.
  const doc = new DOMParser().parseFromString(page.html, 'text/html');
  for (const link of doc.querySelectorAll('a[href]')) {
    const target = link.getAttribute('href');
    if (target.startsWith('wiki://')) link.href = href(target.slice(7), lang);
    else if (target.startsWith('https://')) { link.target = '_blank'; link.rel = 'noopener noreferrer'; }
    else link.removeAttribute('href');
  }
  for (const table of doc.querySelectorAll('table')) {
    const wrap = doc.createElement('div');
    wrap.className = 'table';
    table.replaceWith(wrap);
    wrap.append(table);
  }
  node.replaceChildren(...doc.body.childNodes);
  contents(node);
  document.title = page.title + ' · ' + text('title');
}

async function load({focus = false} = {}) {
  const {lang, page} = route();
  translate(lang);
  try {
    index = await catalogue(lang);
    $('#version').textContent = text('version', {v: index.version});
    let key = page;
    if (!index.entries.some(entry => entry.key === key)) key = 'home';
    render(await article(lang, key), lang);
    $('#notice').hidden = key === page;
    $('#notice').textContent = key === page ? '' : text('missing');
    results();
    if (location.hash) document.getElementById(location.hash.slice(1))?.scrollIntoView();
    if (focus) $('#article').focus({preventScroll: true});
  } catch (error) {
    console.error(error);
    $('#notice').hidden = false;
    $('#notice').textContent = text('failed');
  }
}

function go(url) {
  history.pushState(null, '', url);
  document.body.classList.remove('browse-open');
  $('#browse-toggle').setAttribute('aria-expanded', 'false');
  window.scrollTo({top: 0});
  load({focus: true});
}

labels = await json('/wiki/i18n.json').catch(() => ({en: {}, ru: {}}));
$('#language').addEventListener('change', event => {
  remember(event.target.value);
  go(href(route().page, event.target.value));
});
$('#search').addEventListener('input', () => results());
$('#browse-toggle').addEventListener('click', () => {
  const open = document.body.classList.toggle('browse-open');
  $('#browse-toggle').setAttribute('aria-expanded', String(open));
  if (open) $('#search').focus();
});
document.addEventListener('click', event => {
  const link = event.target.closest('a[href]');
  if (!link || event.defaultPrevented || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
  const url = new URL(link.href);
  if (url.origin !== location.origin || url.pathname !== '/wiki/' || link.target) return;
  event.preventDefault();
  if (url.search === location.search && url.hash) { history.pushState(null, '', url); document.getElementById(url.hash.slice(1))?.scrollIntoView(); return; }
  go(url);
});
window.addEventListener('popstate', () => load());
load();
